  ('w4-l2', 'w4', 2, 'Division och multiplikation hänger ihop', 'Räknefamiljer, saknade tal, division med 1 och 0 – och varför man inte kan dela med noll.', false),
  ('w4-l3', 'w4', 3, 'Division med rest', 'När det inte går jämnt upp: rest, kontroll och hur resten tolkas i en berättelse.', false),
