  ('w4-l5', 'w4', 5, 'Liggande stolen', 'Skriftlig division steg för steg: kvotsiffra, produkt, rest – och varför resten flyttas ner.', false),
  ('w4-l6', 'w4', 6, 'Division med tvåsiffrig delare', 'Dela i omgångar: ta ut tiogrupper först, sedan resten (trappan).', false),
  ('w4-l7', 'w4', 7, 'Överslag, rimlighet och problemlösning', 'Bedöm om en kvot är rimlig och välj rätt tolkning i textuppgifter.', false),
  ('w4-boss', 'w4', 99, 'Bossutmaning: Division', 'Blandat slutprov för hela världen', true),
  ('w5-l1', 'w5', 1, 'Vad är ett bråk?', 'En del av en helhet: täljare, nämnare och varför delarna måste vara lika stora.', false),
  ('w5-l2', 'w5', 2, 'Bråk på tallinjen', 'Bråk som tal med en plats på tallinjen – också bråk större än 1.', false),
