  ('w7-l2', 'w7', 2, 'Procent, bråk och decimaltal', 'Tre namn för samma tal: 1/4 = 0,25 = 25 %.', false),
  ('w7-l3', 'w7', 3, 'Vanliga procent i huvudet', '10 %, 50 %, 25 %, 20 %, 5 % och 1 % – bygg alla andra procent av dem.', false),
  ('w7-l4', 'w7', 4, 'Procent av ett tal', '35 % av 240 – tre metoder: bygga, via 1 % och med decimaltal.', false),
  ('w7-l5', 'w7', 5, 'Dubbel tallinje och proportionalitet', 'Procent växer i takt med beloppet: dubbla procenten, dubbla beloppet.', false),
  ('w7-l6', 'w7', 6, 'Hur många procent är delen?', '12 av 40 är 30 % – gör delen och helheten till hundradelar.', false),
  ('w7-l7', 'w7', 7, 'Hitta helheten', '25 % av ett tal är 15 – vilket är talet? Räkna baklänges med procent.', false),
  ('w7-l8', 'w7', 8, 'Rabatt och prisökning', 'Minska och öka med procent – och varför +20 % och −20 % inte tar ut varandra.', false),
  ('w7-l9', 'w7', 9, 'Jämföra och tolka procent', 'Procent är relativt: helheten avgör – och hur man jämför andelar.', false),
  ('w7-l10', 'w7', 10, 'Procent i vardagen – välj rätt metod', 'Moms, ränta, provresultat och textuppgifter: avgör vad som söks.', false),
