  ('w8-l3', 'w8', 3, 'Jämföra och ordna negativa tal', '−7 är mindre än −2 – större tal ligger längre åt höger.', false),
  ('w8-l4', 'w8', 4, 'Addition och subtraktion med negativa tal', 'Räkna som förflyttningar på tallinjen: plus = åt höger, minus = åt vänster.', false),
  ('w8-l5', 'w8', 5, 'Skillnad och avstånd mellan tal', 'Skillnaden mellan 5 °C och −3 °C är 8 grader – och vad det säger om subtraktion.', false),
  ('w8-l6', 'w8', 6, 'Negativa tal i vardagen', 'Temperatur, bankkonto, hiss och havsdjup – modellera, räkna och kontrollera.', false),
  ('w8-boss', 'w8', 99, 'Bossutmaning: Negativa tal', 'Blandat slutprov för hela världen', true),
  ('w9-l1', 'w9', 1, 'Likhetstecknet – lika mycket på båda sidor', '= betyder ”har samma värde som”, inte ”nu kommer svaret”.', false),
