  ('w9-l8', 'w9', 8, 'Algoritmer – stegvisa instruktioner', 'Följa, beskriva och rätta instruktioner med upprepning och villkor – grunden i programmering.', false),
  ('w9-l9', 'w9', 9, 'Förenkla uttryck', 'Samla lika termer: 3n + 2n = 5n – men 3n + 2 kan inte slås ihop.', false),
  ('w9-boss', 'w9', 99, 'Bossutmaning: Algebra och mönster', 'Blandat slutprov för hela världen', true),
  ('w10-l1', 'w10', 1, 'Månghörningar och deras egenskaper', 'Namn, sidor, vinklar och hur kvadrat, rektangel, romb och parallellogram hänger ihop.', false),
