  ('w10-l3', 'w10', 3, 'Area – rutor, rektanglar och sammansatta figurer', 'Area är hur många enhetsrutor som täcker ytan. Rektangel: längd · bredd.', false),
  ('w10-l4', 'w10', 4, 'Area av parallellogram och trianglar', 'Parallellogram: bas · höjd. Triangel: bas · höjd ÷ 2. Höjden är vinkelrät mot basen.', false),
