  ('w11-l1', 'w11', 1, 'Längd – mm, cm, dm, m och km', 'Välj rätt enhet, läs av en linjal och byt mellan längdenheter.', false),
  ('w11-l2', 'w11', 2, 'Massa – g, kg och ton', 'Hur mycket ”materia” något innehåller. 1 kg = 1 000 g, 1 ton = 1 000 kg.', false),
  ('w11-l3', 'w11', 3, 'Volym och rymd – liter, dl, cl, ml och dm³', '1 l = 10 dl = 100 cl = 1 000 ml, och 1 l = 1 dm³, 1 ml = 1 cm³.', false),
  ('w11-l4', 'w11', 4, 'Tid – sekunder, minuter, timmar och dygn', 'Tid räknas inte i tiopotenser: 60 s = 1 min, 60 min = 1 tim, 24 tim = 1 dygn.', false),
  ('w11-l5', 'w11', 5, 'Area och areaenheter – cm², dm² och m²', '1 m² = 100 dm² = 10 000 cm². Areaenheter byts med 100 per steg, inte 10.', false),
  ('w11-l6', 'w11', 6, 'Skala – ritningar och kartor', 'Skala 1:100 betyder att 1 cm på ritningen är 100 cm i verkligheten.', false),
  ('w11-l7', 'w11', 7, 'Omvandling mellan enheter – systematiskt', 'Prefixen avgör faktorn. Större enhet → mindre tal. Mindre enhet → större tal.', false),
